// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        // Wide domain: no restriction on actor or newOwner. If actor happens to be
        // the admin (this test contract), the mutant agrees with the reference; the
        // assertion below simply permits that case.

        // Admin legitimately sets the owner first (admin == deployer == address(this)).
        vm.prank(address(this));
        assertTrue(c.setOwner(newOwner), "admin can set owner");
        address legitOwner = c.owner();

        // Now an arbitrary fuzzed actor attempts to change the owner.
        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        // GENERAL RULE: c.owner() may only differ from the legitimately set value
        // when the caller is the admin. A non-admin caller must not be able to
        // change the owner (reference: reverts; mutant: succeeds and changes it).
        assertTrue(
            actor == address(this) || (!ok && c.owner() == legitOwner),
            "non-admin caller must not be able to change the owner"
        );
    }
}
